    "kelionwang_153": "種蛋雞繁殖全段",
    "kelionwang_154": "褐藻Fucoidan作為 HPG 軸固醇前驅物，支持 FSH/LH 正常分泌。促性腺激素水平提升後，輸卵管的蛋殼腺（子宮部）鈣化功能同步改善，鈣離子沈積更充分，殼強指數提升，破殼廢蛋率降低。這是間接機轉，而非直接補鈣。",
    "kelionwang_155": "HPG 軸調節後，母雞卵巢功能改善，卵泡發育品質提升，有助於卵細胞品質的整體改善。田間案例顯示受精率同步有所提升，但殼力旺的主要訴求是蛋殼品質和產蛋率，受精率改善為附帶效益，建議同時優化公雞管理以確保受精率。",
    "kelionwang_156": "激素機轉",
    "kelionwang_157": "至少 4 週",
