    "zujinwang_0": "活力得<span>®</span>",
    "zujinwang_1": "首頁",
    "zujinwang_10": "蛋白酶促進腸道消化 · 胸肉率提升 · 整齊度改善<br/>開食期 · 生長期 · 育肥期 全段適用",
    "zujinwang_100": "大豆粕佔飼料原料超過 30%，蛋白消化率改善空間最大，效益最顯著。",
    "zujinwang_101": "胸肉率要求高場",
    "zujinwang_102": "供應胸肉分切的肉雞場，胸肉率每提升 1%，批次溢價空間相當可觀。",
    "zujinwang_103": "整齊度差批次",
    "zujinwang_104": "出欄個體差異大，屠場收購評級受影響，需改善消化均一性。",
    "zujinwang_105": "腸道健康問題場",
