    "zujinwang_109": "白羽肉雞場",
    "zujinwang_11": "FCR 料肉比",
    "zujinwang_110": "白羽肉雞生長速度快、飼料敏感，蛋白酶可最大化飼料蛋白利用效率。",
    "zujinwang_111": "（原圖英文 Traditional／Optimized／Feed Reduction）",
