    "zujinwang_160": "白羽肉雞、黃羽肉雞及土雞",
    "zujinwang_161": "蛋白酶水解大豆粕後，游離胺基酸（特別是亮氨酸、纈氨酸等支鏈胺基酸）的吸收率提升，這些胺基酸是胸肌合成的主要原料。胺基酸供給更充分後，胸肌蛋白沈積量增加，胸肉率自然提升。田間案例顯示提升幅度約 <strong>+15.24%</strong>（田間/產業參考）。",
    "zujinwang_162": "整齊度（CV，變異係數）直接影響屠場批次收購評級。CV 越低（&lt;8%），同批雞個體重量越集中，屠場評級越高，收購單價更穩定。足斤旺通過改善消化均一性，使每隻雞的蛋白吸收量更接近，個體差異縮小，CV 從 12% 降至 8% 可帶來屠場評級的實際收益。",
    "zujinwang_163": "1 kg 足斤旺兌 1 噸飼料",
    "zujinwang_164": "兩步放大稀釋法",
