    "kelionwang_153": "种蛋鸡繁殖全段",
    "kelionwang_154": "褐藻Fucoidan作为 HPG 轴固醇前驱物，支持 FSH/LH 正常分泌。促性腺激素水平提升后，输卵管的蛋壳腺（子宫部）钙化功能同步改善，钙离子沉积更充分，壳强指数提升，破壳废蛋率降低。这是间接机转，而非直接补钙。",
    "kelionwang_155": "HPG 轴调节后，母鸡卵巢功能改善，卵泡发育品质提升，有助于卵细胞品质的整体改善。田间案例显示受精率同步有所提升，但壳力旺的主要诉求是蛋壳品质和产蛋率，受精率改善为附带效益，建议同时优化公鸡管理以确保受精率。",
    "kelionwang_156": "激素机转",
    "kelionwang_157": "至少 4 周",
