    "zujinwang_160": "白羽肉鸡、黄羽肉鸡及土鸡",
    "zujinwang_161": "蛋白酶水解大豆粕后，游离胺基酸（特别是亮氨酸、缬氨酸等支链胺基酸）的吸收率提升，这些胺基酸是胸肌合成的主要原料。胺基酸供给更充分后，胸肌蛋白沉积量增加，胸肉率自然提升。田间案例显示提升幅度约 <strong>+15.24%</strong>（田间/产业参考）。",
    "zujinwang_162": "整齐度（CV，变异系数）直接影响屠场批次收购评级。CV 越低（&lt;8%），同批鸡个体重量越集中，屠场评级越高，收购单价更稳定。足斤旺通过改善消化均一性，使每只鸡的蛋白吸收量更接近，个体差异缩小，CV 从 12% 降至 8% 可带来屠场评级的实际收益。",
    "zujinwang_163": "1 kg 足斤旺兑 1 吨饲料",
    "zujinwang_164": "两步放大稀释法",
