    "kelionwang_153": "Breeder layer hens (entire breeding cycle)",
    "kelionwang_154": "As an HPG axis sterol precursor, phytosterol supports normal secretion of FSH/LH. Elevated gonadotropin levels simultaneously improve calcification function of the shell gland (uterus) in the oviduct, leading to more complete calcium deposition, increased shell strength index, and reduced cracked egg waste rate. This is an indirect mechanism, not direct calcium supplementation.",
