    "zujinwang_160": "White-feather Broiler, Yellow-feather Broiler, and Local Chicken",
    "zujinwang_161": "After protease hydrolysis of soybean meal, the absorption rate of free amino acids (especially branched-chain amino acids such as leucine and valine) increases. These amino acids are the primary raw materials for breast muscle synthesis. With more sufficient amino acid supply, breast muscle protein deposition increases, naturally raising the breast meat ratio. Field cases show an improvement of approximately <strong>+15.24%</strong> (field/industry reference).",
    "zujinwang_162": "Uniformity (CV, coefficient of variation) directly affects slaughterhouse batch purchase grading. The lower the CV (&lt;8%), the more concentrated the individual weights within the batch, leading to higher slaughterhouse grading and more stable purchase unit prices. ZuJinWang improves digestive uniformity, making the protein absorption of each broiler closer to the average, reducing individual differences. Reducing CV from 12% to 8% can bring actual benefits in slaughterhouse grading.",
    "zujinwang_163": "1 kg ZuJinWang per 1 ton of feed",
    "zujinwang_164": "Two-step amplification dilution method",
